const industries=rows.map(([name,intro,fams,ex])=>{let id=slug(name),codes=fams.split(',');return {id,name,description_en:intro+' EVA PRINT combines engineering review, material selection and custom FFF printing for the project.',material_families:codes,suggested_material_ids:materials.filter(m=>codes.includes(m.family_code)&&m.service_status!=='not_verified_for_current_fleet').slice(0,16).map(m=>m.id),application_examples:ex.split('|').map((title,i)=>({id:id+'-example-'+(i+1),title,description:'Proposed application: '+title+'. Submit CAD or reference documents, intended operating conditions, quantity and acceptance requirements for an engineering review.',kind:'proposed_application',eva_print_completed_project:false})),external_references:cases.filter(c=>c.industries.includes(name)).map(c=>c.id),engineering_notes:'Examples are proposed uses. Suitability depends on design, material grade, production conditions and verification of the finished part. Regulated or critical uses require the relevant qualified process.',publish_status:'editorial_draft'};}).sort((a,b)=>a.name.localeCompare(b.name));
