await fs.writeFile(path.join(root,'03_INDUSTRIES/industries.en.json'),JSON.stringify(industries,null,2));await fs.writeFile(path.join(root,'03_INDUSTRIES/documented-external-cases.json'),JSON.stringify(cases,null,2));
